(1, 'index.php?option=com_content&view=article&id=1', 'index.php?option=com_content&view=article&id=1:index&catid=2', 'Главная', '', '2024-02-19 13:39:01', 'fb1e6f1663af01efef45c764247ef5c4', 1, 1, 1, '*', '2024-02-19 13:39:01', NULL, '2024-02-19 13:39:01', NULL, 0, 0, 3, ),
(2, 'index.php?option=com_content&view=article&id=2', 'index.php?option=com_content&view=article&id=2:sdfgsdfg&catid=2', 'sdfgsdfg', 'xdzfgsd', '2025-06-10 11:14:06', '15e0866651da8cb3becc237eb06fb3ba', 1, 0, 1, '*', NULL, NULL, '2025-06-10 11:14:06', NULL, 0, 0, 3, ),
(3, 'index.php?option=com_content&view=article&id=3', 'index.php?option=com_content&view=article&id=3:about&catid=2&lang=uk-UA', 'Про нас', ' О нас HealthyDriedFood — надійний постачальник натуральних сушених продуктів оптом з доставкою по всій Україні Ми спеціалізуємося на продажу якісних сушених фруктів, овочів, м’яса та трав. Завдяки ретельному відбору сировини, контролю якості та професійному підходу ми пропонуємо вигідні умови для бізнесу і здорового харчування. Що пропонує HealthyDriedFood Асортимент: сушені фрукти, овочі, м’ясо, трави та інші натуральні продукти Ми співпрацюємо з магазинами здорового харчування, дистриб’юторами, кафе та ресторанами, допомагаючи їм економити час і кошти завдяки прямим постачанням та перевіреним виробникам. Доставка по всій Україні Нова пошта, кур’єр, самовивіз, Укрпошта ', '2025-08-29 07:45:26', '1aa2320795c1ede751ff39046de76cf5', 1, 1, 1, 'uk-UA', '2025-06-10 17:10:24', NULL, '2025-06-10 17:10:24', NULL, 0, 0, 3, );
