(158, 164, 'Main advan RU', '', '<div class=\"main-advan mb10\">\r\n<div class=\"container-wide\">\r\n<div class=\"wrapper\">\r\n<div class=\"container\">\r\n<div class=\"main-advan-list flex between\">\r\n<div class=\"item\">\r\n<div class=\"ico\" style=\"background-image: url(\'/images/main/advan1.svg\');\">&nbsp;</div>\r\n<div class=\"text-box\">\r\n<div class=\"ttl\">Доставка</div>\r\n<div class=\"text\">Быстрая доставка по всей Украине</div>\r\n</div>\r\n</div>\r\n<div class=\"item\">\r\n<div class=\"ico\" style=\"background-image: url(\'/images/main/advan2.svg\');\">&nbsp;</div>\r\n<div class=\"text-box\">\r\n<div class=\"ttl\">Условия покупки</div>\r\n<div class=\"text\">Минимальный заказ от 500 грн</div>\r\n</div>\r\n</div>\r\n<div class=\"item\">\r\n<div class=\"ico\" style=\"background-image: url(\'/images/main/advan3.svg\');\">&nbsp;</div>\r\n<div class=\"text-box\">\r\n<div class=\"ttl\">Выгодные цены</div>\r\n<div class=\"text\">Сезонные акции и выгодные предложения</div>\r\n</div>\r\n</div>\r\n<a href=\"/\" target=\"_blank\" class=\"item channel icon-telegram\">\r\n<div class=\"text-box\">\r\n<div class=\"ttl\">Телеграмм-канал <br />OnlineShop</div>\r\n</div>\r\n</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 1, 'main-advan', NULL, NULL, NULL, NULL, 1, 'mod_custom', 1, 0, '{\"prepare_content\":0,\"backgroundimage\":\"\",\"layout\":\"_:default\",\"moduleclass_sfx\":\"\",\"cache\":1,\"cache_time\":900,\"cachemode\":\"static\",\"module_tag\":\"div\",\"bootstrap_size\":\"0\",\"header_tag\":\"h3\",\"header_class\":\"\",\"style\":\"0\"}', 0, 'ru-RU'),
